validation_start = pd.Timestamp("2025-09-01")
fit_df = df.loc[df.date < validation_start].copy()
val_df = df.loc[df.date >= validation_start].copy()
splits = {"Training": fit_df, "Internal validation": val_df}
split_summary = pd.DataFrame([
    {"split": name, "rows": len(part), "start": part.date.min().date(),
     "end": part.date.max().date(), "share_pct": round(100 * len(part) / len(df), 2)}
    for name, part in splits.items()
]).set_index("split")
display(split_summary)

dummy = DummyRegressor(strategy="median")
dummy.fit(np.zeros((len(y_fit), 1)), y_fit)
dummy_predictions = dummy.predict(np.zeros((len(y_val), 1)))
candidate_models = {
    "Ridge": Pipeline([
        ("preprocess", clone(preprocessor)),
        ("regressor", Ridge(alpha=10.0, solver="lsqr")),
    ]),
    "Log-target Ridge": Pipeline([
        ("preprocess", clone(preprocessor)),
        ("regressor", TransformedTargetRegressor(
            regressor=Ridge(alpha=10.0, solver="lsqr"), func=np.log, inverse_func=np.exp)),
    ]),
}
MIN_PREDICTED_RATE = 0.01

def predict_rates(estimator, features):
    prediction = np.asarray(estimator.predict(features), dtype=float)
    if not np.isfinite(prediction).all():
        raise ValueError("Nonfinite rate predictions")
    return np.maximum(prediction, MIN_PREDICTED_RATE)

def scores(name, prediction, floored=0):
    return {"model": name, "MAE": mean_absolute_error(y_val, prediction),
            "RMSE": np.sqrt(mean_squared_error(y_val, prediction)),
            "R2": r2_score(y_val, prediction), "floored_predictions": floored}

score_rows = [scores("Training median", dummy_predictions)]
candidate_predictions = {}
for name, estimator in candidate_models.items():
    estimator.fit(X_fit, y_fit)
    raw_predictions = estimator.predict(X_val)
    candidate_predictions[name] = predict_rates(estimator, X_val)
    score_rows.append(scores(name, candidate_predictions[name],
                             int((raw_predictions < MIN_PREDICTED_RATE).sum())))
validation_scores = pd.DataFrame(score_rows).set_index("model")
display(validation_scores.round(3))
selected_name = validation_scores.loc[list(candidate_models), "MAE"].idxmin()
model = candidate_models[selected_name]
val_predictions = candidate_predictions[selected_name]
gain = 100 * (1 - validation_scores.loc[selected_name, "MAE"] /
                  validation_scores.loc["Training median", "MAE"])
print(f"Selected: {selected_name}; MAE improvement over median: {gain:.1f}%")
